+//
+
+#define TPETRA_LINEARPROBLEM_INSTANT(SCALAR,LO,GO,NODE) \
+  template class LinearProblem< SCALAR , LO , GO , NODE >;
+
+
+#endif // TPETRA_LINEARPROBLEM_DEF_HPP

