+int main (int argc, char** argv)
+{
+  std::cout << "Starting MAIN\n";
+
+  {
+    std::cout << "Begin Setting Kokkos profiling\n";
+    using namespace Kokkos::Profiling;
+    using namespace Kokkos::Profiling::Experimental;
+
