+  /// We cache these multivectors here to avoid creating them on each call.
   Teuchos::RCP<MV> W_;
+  Teuchos::RCP<MV> W2_;

   /// \brief Estimate that we compute for maximum eigenvalue of A.
   ///
@@ -556,6 +557,14 @@ class Chebyshev : public Teuchos::Describable {
   /// calling apply() many times.
   Teuchos::RCP<MV> makeTempMultiVector (const MV& B);

+  /// \brief Set W2 to temporary MultiVector with the same Map as B.
+  ///
+  /// This is an optimization for apply(). This method caches the
+  /// created MultiVector as W2_. Caching optimizes the common case of
+  /// calling apply() many times. This is used by fourth kind
+  /// Chebyshev as two temporary multivectors are needed.
+  Teuchos::RCP<MV> makeSecondTempMultiVector (const MV& B);
+
   //! W = alpha*D_inv*B and X = 0 + W.
   void
   firstIterationWithZeroStartingSolution

@@ -1350,8 +1350,10 @@ fourthKindApplyImpl (const op_type& A,
   MV& Z = *Z_ptr;

   // Store 4th-kind result (needed as temporary for bootstrapping opt. 4th-kind Chebyshev)
-  MV X4 (B.getMap (), B.getNumVectors (), false);
-  
+  // Fetch the second cached temporary (multi)vector.
+  Teuchos::RCP<MV> X4_ptr = makeSecondTempMultiVector (B);
+  MV& X4 = *X4_ptr;
+
   // Special case for the first iteration.
   if (! zeroStartingSolution_) {

@@ -1653,6 +1655,23 @@ makeTempMultiVector (const MV& B)
   return W_;
 }

+template<class ScalarType, class MV>
+Teuchos::RCP<MV>
+Chebyshev<ScalarType, MV>::
+makeSecondTempMultiVector (const MV& B)
+{
+  // ETP 02/08/17:  We must check not only if the temporary vectors are
+  // null, but also if the number of columns match, since some multi-RHS
+  // solvers (e.g., Belos) may call apply() with different numbers of columns.
+
+  const size_t B_numVecs = B.getNumVectors ();
+  if (W2_.is_null () || W2_->getNumVectors () != B_numVecs) {
+    W2_ = Teuchos::rcp (new MV (B.getMap (), B_numVecs, false));
+  }
+  return W2_;
+}
+
