+#endif
+#ifndef XPETRA_EPETRA_NO_64BIT_GLOBAL_INDICES
+typedef long long LongLong;
+XPETRA_EPETRA_TYPES(double,int,LongLong,EpetraNode)
+XP_IO_INSTANT(double,int,LongLong,EpetraNode)
+#endif
+
+#endif
+
+}

