+              << "Residual 1-norm: " << BVecYOrig.norm1 () << std::endl
+              << "Residual Inf-norm: " << BVecYOrig.normInf () << std::endl;
+
+    const bool normSmallEnough = (norm <= as<MT> (1e-10));
+    TEST_EQUALITY ( normSmallEnough, true );
+  }
