+    ScalarType lambdaMax = STS::one();
+    if( N > 2 ) {
+      Teuchos::LAPACK<int,ScalarType> lapack;
+      lapack.PTEQR (char_N, N, diag.getRawPtr (), offdiag.getRawPtr (),
