+        default:
+          out << "Pass/Fail is checked only for 1 and 4 processes." << std::endl;
+          break;
+      } // switch
+
+      // make sure the Ifpack2 preconditioner did not get replaced
+      TEUCHOS_ASSERT_EQUALITY(ifpack2prec.ptr(), smoother.getPreconditioner().ptr());
+
+    }
+  } // Jacobi
