+            << ", Right-hand side norm: "
+            << b_norm
+            << ", Implicit and explicit residual norms: "
+            << r_norm_imp << ", " << r_norm
+            << " -> "
+            << r_norm_imp/b_norm << ", " << r_norm/b_norm
+            << ", Ortho error: "
+            << ortho_error
+            << ", Arnoldi representation error: "
+            << repre_error
+            << ", Projection error: "
+            << proje_error
