+          columnScalarValues[colId] = elemsMat(elemId, nodeId, colId);
+
+        A->sumIntoLocalValues(localRowId, columnLocalIds, columnScalarValues);
+        b->sumIntoLocalValue(columnLocalIds[nodeId], 0, elemsRHS(elemId, nodeId));
+      }
+    }
