+        // For each node (row) on the current element
+        for (local_ordinal_t nodeId = 0; nodeId < basisCardinality; ++nodeId) {
+          const local_ordinal_t localRowId = elementLIDs(elemId,elmtOffsetKokkos(nodeId));
