+  TEUCHOS_UNIT_TEST_TEMPLATE_4_INSTANT(LWGraph_kokkos, LocalGraphData, SC, LO, GO, NO)
+
+#include <MueLu_ETI_4arg.hpp>
+
+} // namespace MueLuTests

