+#include "MantidCurveFitting/Functions/BackgroundFunction.h"
+
+namespace Mantid {
+namespace CurveFitting {
+namespace Functions {
+/**
+Provide Activation fit function for data in meV interface to IFunction.
+I.e. function: y = AttemptRate*exp(-e*Barrier/(1000 k_B x))
+
+Activation parameters:
+<UL>
+<LI> AttemptRate - coefficient for attempt rate (default 1000.0)</LI>
+<LI> Barrier - coefficient for barrier energy (default 1000.0)</LI>
+</UL>
+*/
+
+class MANTID_CURVEFITTING_DLL ActivationmeV : public BackgroundFunction {
+public:
+  /// overwrite IFunction base class methods
+  std::string name() const override { return "ActivationmeV"; }
+  void function1D(double *out, const double *xValues, const size_t nData) const override;
+  void functionDeriv1D(API::Jacobian *out, const double *xValues, const size_t nData) override;
+  const std::string category() const override { return "Muon\\MuonModelling"; }
+
+protected:
+  /// overwrite IFunction base class method, which declare function parameters
+  void init() override;
+};
+
+} // namespace Functions
+} // namespace CurveFitting
+} // namespace Mantid

