+    TS_ASSERT(newPW);
+
+    // retrieve the peak
+    IPeak &iPeak = newPW->getPeak(0);
+    Peak *const peak = dynamic_cast<Peak *>(&iPeak);
+    TS_ASSERT(peak);
+
