+ */
+void Axes::tickLabelFormat(const char *axis, const char *style,
+                           const bool useOffset) {
+  try {
+    GlobalInterpreterLock lock;
+    Python::List args;
+    Python::Dict kwargs;
+    kwargs["axis"] = axis;
+    kwargs["style"] = style;
+    kwargs["useOffset"] = useOffset;
+    pyobj().attr("ticklabel_format")(*args, **kwargs);
+  } catch (...) {
+    throw PythonException();
+  }
+}
