+                sy = std::copysign(Real(1.),dc)*amrex::min(sy,std::abs(dc));
+                if (dc != Real(0.0)) {
+                    sfy = amrex::min(sfy, sy / dc);
+                }
+                Real slope = dc;
+                Real yoff = (static_cast<Real>(j - cj*ratio[1]) + Real(0.5)) / Real(ratio[1]) - Real(0.5);
+                fine(i,j,k,n) += yoff * slope * sfy;
+            } // cj
+        } // mask
+    } // dim == 2
+#endif
+}
