+    if (j == domain.bigEnd(1) && (bc.hi(1) == BCType::ext_dir ||
+                                  bc.hi(1) == BCType::hoextrap)) {
+        if (j-2 >= u.begin.y) {
+            yy = 0._rt;
+        }
+    }
+    return yy;
 }

