+        dmap[lev] = DistributionMapping{ba[lev]};
+    }
+
+    typedef AmrParticleContainer<4, 0, 0, 0> MyParticleContainer;
+    using PType = typename amrex::ParticleContainer<4, 0>::SuperParticleType;
