+namespace {
+amrex::Real dot_product(const std::array<amrex::Real,3>& a, const std::array<amrex::Real,3>& b) 
+{
+   return a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
+}
+
+bool intersects(amrex::Real val)
+{
+   return (val > 0.0 && val < 1.0);
+}
