-  write(100,'(A)') '<Coordinates>'
-
-  call data_array(problo(1), lo(1), nodes(1), dx(1))
-  call data_array(problo(2), lo(2), nodes(2), dx(2))
-  call data_array(problo(3), lo(3), nodes(3), dx(3))
